package com.yilu.yinling;
import com.yilu.yinling.ai.client.*; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.Assumptions; import static org.junit.jupiter.api.Assertions.*;
class RealLlmIntegrationTest {
 @Test void realDeepSeekCallReturnsAnswerAndMetrics(){String key=System.getenv("DEEPSEEK_API_KEY");Assumptions.assumeTrue(key!=null&&!key.isBlank(),"DEEPSEEK_API_KEY not configured; real integration skipped");var properties=new LlmProperties();properties.setEnabled(true);properties.setProvider("deepseek");properties.getDeepseek().setApiKey(key);properties.getDeepseek().setBaseUrl(System.getenv().getOrDefault("DEEPSEEK_BASE_URL","https://api.deepseek.com"));properties.getDeepseek().setModel(System.getenv().getOrDefault("DEEPSEEK_MODEL","deepseek-chat"));var state=new LlmRuntimeState();var answer=new DeepSeekLlmClient(properties,new MockLlmClient(),state).chat("你是养老金融知识助手。","你好，请介绍一下养老金融。");assertFalse(answer.isBlank());assertTrue(state.isAvailable(),state.getMessage());assertFalse(state.isFallback());assertNotNull(state.getLastMetrics());assertEquals("deepseek",state.getLastMetrics().provider());assertTrue(state.getLastMetrics().latency()>=0);assertTrue(state.getLastMetrics().answerLength()>0);}
}
